def build_db_options(
    args: argparse.Namespace, resolver: SecretResolver | None = None
) -> DbOptions:
    """Resolve the database flags against the environment, raising ValueError if unusable."""
    resolver = resolver or SecretResolver()
    enabled = args.db_store or _env_flag("SECMAN_DB_STORE")
    # The whole DSN can be one reference: the password inside it would otherwise
    # be the single worst thing to have on a command line.
    url = resolver.resolve(
        args.db_url or os.environ.get("SECMAN_DB_URL"), what="--db-url"
    )
    overrides = {
        "enabled": enabled,
        "table_prefix": args.db_table_prefix,
        "fail_on_error": args.db_fail_on_error,
    }
    if url:
        options = DbOptions.from_url(url, **overrides)
    else:
        options = DbOptions(
            host=args.db_host or os.environ.get("SECMAN_DB_HOST") or "127.0.0.1",
            port=args.db_port or int(os.environ.get("SECMAN_DB_PORT") or 3306),
            user=args.db_user or os.environ.get("SECMAN_DB_USER") or "",
            password=resolver.resolve(
                args.db_password or os.environ.get("SECMAN_DB_PASSWORD"),
    return (os.environ.get(name) or "").strip().lower() in ("1", "true", "yes", "on")


def _emit(writer, *args, secrets: Sequence[str] = (), **kwargs) -> None:
    """Run a report writer, then scrub resolved secrets out of what it printed.

    Every one of these writers echoes text from somewhere else — a SecMan error
    body, a database driver's message. A backend that rejects a credential by
    quoting it back must not get it into the console output or a CI log, so the
    output goes through a buffer on its way to stdout rather than straight to it.
    """
    buffer = io.StringIO()
    writer(*args, stream=buffer, **kwargs)
    sys.stdout.write(redact(buffer.getvalue(), secrets))


def _run_secman_upload(
    report, options: SecmanOptions, fail_on_error: bool, secrets: Sequence[str] = ()
) -> int:
    """Upload a report's findings and turn the result into an exit code."""
    try:
        summary = upload_findings(report, options)
    except SecmanError as exc:
        print(f"error: SecMan upload failed: {redact(str(exc), secrets)}", file=sys.stderr)
        return EXIT_ERROR
    _emit(write_upload_report, summary, secrets=secrets)
    if (summary.failures or summary.asset_failures) and fail_on_error:
        return EXIT_ERROR
    return EXIT_OK


def _progress_hook(quiet: bool, secrets: Sequence[str] = ()):
    """Build the per-target progress line printed as the scan runs.

    ``result.error`` and ``capture.load_error`` can carry text a scanned
    target controls (a rejected-credential provider error, a page that
    quotes back the headers it received) — the exact same fields
    ``reporting.redact_report`` scrubs before any report is written. This
    line is printed live, before that redaction ever runs, so it needs its
    own pass through :func:`redact` or a resolved secret reflected back by a
    target reaches stderr in the clear.
    """

    def hook(result: ScanResult, done: int, total: int) -> None:
        if quiet:
            return
        if result.skipped_reason:
            state = f"skipped ({result.skipped_reason})"
        elif result.error:
            state = f"error: {redact(result.error, secrets)}"
        elif result.capture and result.capture.load_error:
            state = f"load failed: {redact(result.capture.load_error, secrets)}"
        else:
            state = result.max_severity.value
        prefix = f"{result.status_check.label} | " if result.status_check else ""
        print(f"[{done}/{total}] {result.url} -> {prefix}{state}", file=sys.stderr, flush=True)

    return hook


def _report_outputs(args: argparse.Namespace, config: ScanConfig) -> list[tuple[str, Path]]:
    """The files a run would write, in the order it would write them."""
    outputs: list[tuple[str, Path]] = []
    if config.visual_check:
        outputs.append(("screenshots", config.screenshot_dir))
    for name, flag, override, filename in (
        ("json", args.no_json, args.json, "report.json"),
        ("html", args.no_html, args.html, "report.html"),
        ("csv", args.no_csv, args.csv, "report.csv"),
        ("statistics", args.no_stats, args.stats, "statistics.txt"),
    ):
        if not flag:
            outputs.append((name, Path(override) if override else config.output_dir / filename))
    return outputs


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    # One switch, applied before anything is built: a dry run must not be able
    # to write through a stage that was never told about it.
    if args.dry_run:
        args.secman_dry_run = True
        args.mail_dry_run = True

    resolver = build_secret_resolver(args)

    upload_requested = args.secman_upload or args.secman_upload_report
    try:
        # Fail before the scan: a ten-minute crawl should not end on a typo in
        # the credentials, nor on a pass:// reference that names nothing.
        secman_options = (
            build_secman_options(args, resolver) if upload_requested else None
        )
        db_options = build_db_options(args, resolver)
        mail_options = build_mail_options(args, resolver)
    except (ValueError, SecretError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return EXIT_ERROR

    # Flagging URLs is a standalone command; there is nothing to scan.
    if args.db_set_flag:
        try:
            assignments = parse_flag_assignments(args.db_set_flag)
        except argparse.ArgumentTypeError as exc:
            print(f"error: {exc}", file=sys.stderr)
            return EXIT_ERROR
        # Reuse the same credential rules as a storing run, whether or not
        # --db-store was passed.
        db_options.enabled = True
        try:
            db_options.validate()
        except ValueError as exc:
            print(f"error: {exc}", file=sys.stderr)
            return EXIT_ERROR
        if args.dry_run:
            # Deliberately offline. Reading the current flags would make a nicer
            # preview, but it would also mean a dry run of a two-line command
            # needs a reachable database and an installed driver.
            write_plan(
                ScanPlan(
                    action=f"set URL flags in {db_options.dsn}",
                    secrets=resolver.resolved,
                    notes=[
                        "Would set:\n"
                        + "\n".join(f"  {flag:<12} {url}" for url, flag in assignments)
                    ],
                )
            )
            return EXIT_OK
        try:
            changes = set_flags(assignments, db_options)
        except (ValueError, DatabaseError) as exc:
            print(f"error: {exc}", file=sys.stderr)
            return EXIT_ERROR
        write_flag_report(changes)
        return EXIT_OK

    # Uploading a stored report is a standalone mode; there is nothing to scan.
    if args.secman_upload_report:
        try:
            stored = load_report_json(args.secman_upload_report)
        except SecmanError as exc:
            print(f"error: {exc}", file=sys.stderr)
            return EXIT_ERROR
        assert secman_options is not None
        return _run_secman_upload(
            stored, secman_options, args.secman_fail_on_error, resolver.values
        )

    if not args.urls and not args.file and not args.stdin:
        parser.error("no targets given; pass URLs, --file PATH or --stdin")

    try:
        targets = load_targets(args.urls, args.file, args.stdin)
    except TargetError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return EXIT_ERROR

    if not targets:
        print("error: no valid targets after parsing input", file=sys.stderr)
        return EXIT_ERROR

    try:
        config = build_config(args, resolver)
    except (argparse.ArgumentTypeError, ValueError, OSError, SecretError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return EXIT_ERROR

    if args.dry_run:
        if args.quiet:
            # The original --dry-run output, kept verbatim so scripts that pipe
            # the target list into something else keep working.
            for url in targets:
                print(url)
            return EXIT_OK
        write_plan(
            ScanPlan(
                targets=targets,
                config=config,
                outputs=_report_outputs(args, config),
                db=db_options,
                mail=mail_options,
                secman=secman_options,
                secrets=resolver.resolved,
            )
        )
        return EXIT_OK

    if not args.quiet:
        if not config.visual_check:
            workers = f"{config.status_check.max_concurrency} status worker(s)"
            mode = "no browser (status check only)"
        else:
            workers = f"{config.concurrency} browser worker(s)"
            mode = "capture only" if config.analyzer is None else config.analyzer.model
        print(
            f"Scanning {len(targets)} target(s) with {workers}; analysis: {mode}",
            file=sys.stderr,
        )

    try:
        report = asyncio.run(
            run_scan(
                targets,
    if db_options.enabled:
        summary = store_report(report, db_options)
        _emit(write_db_report, summary, secrets=resolver.values)
        flag_changes = summary.flag_changes
        if summary.error and db_options.fail_on_error:
            db_status = EXIT_ERROR

    if mail_options.enabled:
        # After the database, so the email can report which URLs are new or
        # changed — that is the part a human actually wants mailed.
        mail_summary = send_report(
            report,
            mail_options,
            flag_changes=flag_changes,
            dashboard_url=args.mail_dashboard_url,
            secrets=resolver.values,
        )
        _emit(write_mail_report, mail_summary, secrets=resolver.values)

    upload_status = EXIT_OK
    if secman_options is not None:
        upload_status = _run_secman_upload(
            report, secman_options, args.secman_fail_on_error, resolver.values
        )

    if config.fail_on is not None and report.max_severity.rank >= config.fail_on.rank:
        if any(f.severity.rank >= config.fail_on.rank for r in report.results for f in r.findings):
            return EXIT_FINDINGS
    if args.fail_on_status and report.status_failures:
        return EXIT_FINDINGS
    return upload_status or db_status


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())
"""What a run *would* do — the `--dry-run` mode.

A scan is slow, spends money on model calls, writes files, rows and emails, and
files vulnerabilities in a tracker. All of that is configured from about ninety
flags and two dozen environment variables, and the usual way to find out whether
you got it right is to run it. This module is the other way: it resolves exactly
the same configuration, down to fetching every credential, and then prints the
plan instead of executing it.

The guarantee is narrow and worth stating precisely: **a dry run writes
nothing** — no report file, no screenshot, no database row, no email, no SecMan
vulnerability — and never launches the browser or calls the model. It is not an
offline mode. Resolving a ``pass://`` reference talks to Proton Pass, and a
SecMan dry run with credentials still *reads* from SecMan to tell you which
findings are already filed. Reads are what make the plan worth reading.

The plan is assembled from the very objects the run would use — a
:class:`~secman_visual_check.config.ScanConfig`, the DB, mail and SecMan option
objects — so it cannot drift from what actually happens. Anything printed here
comes from those objects or from ``endpoint``/``dsn`` properties that are
documented never to contain a secret.
"""

from __future__ import annotations

import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Sequence, TextIO

from .config import ScanConfig
from .db import DbOptions
from .mailer import MailOptions
from .secman import SecmanOptions
from .secrets import SecretRef

WIDTH = 72


@dataclass
class ScanPlan:
    """One run, described rather than performed."""

    targets: Sequence[str] = ()
    config: ScanConfig | None = None
    outputs: list[tuple[str, Path]] = field(default_factory=list)
    db: DbOptions | None = None
    mail: MailOptions | None = None
    secman: SecmanOptions | None = None
    #: References resolved while building the plan. Names, never values.
    secrets: Sequence[SecretRef] = ()
    #: Standalone modes describe themselves instead of a scan.
    action: str = "scan"
    notes: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "action": self.action,
            "targets": list(self.targets),
            "outputs": {name: str(path) for name, path in self.outputs},
            "secrets": [str(ref) for ref in self.secrets],
            "notes": list(self.notes),
        }


def _stage_lines(config: ScanConfig) -> list[tuple[str, str]]:
    """One line per pipeline stage: is it on, and with what."""
    lines: list[tuple[str, str]] = []

    status = config.status_check
    if status.enabled:
        expected = ",".join(str(code) for code in status.expect_statuses[:6])
        if len(status.expect_statuses) > 6:
            expected += ",…"
        method = {
            "auto": "HEAD, falling back to GET",
            "head": "HEAD",
            "get": "GET",
        }.get(status.method, status.method)
        detail = (
            f"{method}, expect {expected}, "
            f"{status.max_concurrency} worker(s), "
            f"{'checksums on' if status.checksum else 'no checksums'}, "
            f"{status.max_redirects} redirect hop(s)"
        )
        lines.append(("status check", detail))
    else:
        lines.append(("status check", "disabled (--no-status-check)"))

    if config.visual_check:
        capture = config.capture
        shape = "full page" if capture.full_page else "viewport only"
        if capture.full_page and capture.max_capture_height:
            shape += f" (max {capture.max_capture_height}px)"
        lines.append(
            (
                "browser",
                f"{capture.viewport_width}x{capture.viewport_height}, {shape}, "
                f"{config.concurrency} worker(s), {capture.timeout_ms / 1000:g}s timeout",
            )
        )
    else:
        lines.append(("browser", "disabled (--no-visual-check) — no Chromium needed"))

    if config.analyzer is not None:
        analyzer = config.analyzer
        key = "API key set" if analyzer.api_key else "NO API KEY — the run would fail"
        lines.append(
            (
                "analysis",
                f"{analyzer.model} via {analyzer.base_url}, "
                f"{config.ai_concurrency} worker(s), {key}",
            )
        )
    elif config.visual_check:
        lines.append(("analysis", "disabled (--no-ai) — screenshots only"))
    else:
        lines.append(("analysis", "disabled (no browser, so nothing to look at)"))

    return lines


def _missing_mail_setting(mail: MailOptions) -> str:
    """What a real send would still refuse over. Empty when it is ready to go."""
    if mail.transport == "smtp" and not mail.smtp_host:
        return "NO SMTP HOST — a real send would fail"
    if mail.transport == "o365" and not (mail.tenant_id and mail.client_id and mail.client_secret):
        return "INCOMPLETE GRAPH CREDENTIALS — a real send would fail"
    if mail.transport == "ses" and not mail.aws_region:
        return "NO AWS REGION — a real send would fail"
    return ""


def _integration_lines(plan: ScanPlan) -> list[tuple[str, str]]:
    lines: list[tuple[str, str]] = []
    if plan.action != "scan":
        # A standalone command touches exactly one thing, named in `action`.
        # Listing the stages it does not use would be noise.
        return lines

    if plan.db is not None and plan.db.enabled:
        lines.append(("database", f"would write status rows to {plan.db.dsn}"))
    else:
        lines.append(("database", "disabled"))

    if plan.mail is not None and plan.mail.enabled:
        when = "always" if plan.mail.always else "only when something is wrong"
        recipients = ", ".join(plan.mail.recipients) or "nobody"
        # A dry run relaxes the transport checks so the plan can be seen without
        # credentials — which makes saying what is still missing its job.
        missing = _missing_mail_setting(plan.mail)
        lines.append(
            (
                "email",
                f"would send via {plan.mail.endpoint} to {recipients} ({when})"
                + (f" — {missing}" if missing else ""),
            )
        )
    else:
        lines.append(("email", "disabled"))

    if plan.secman is not None:
        options = plan.secman
        extras = []
        if not options.has_credentials:
            extras.append("NO CREDENTIALS — a real upload would be refused")
        if options.status_findings:
            extras.append("status failures included")
        if options.register_assets:
            extras.append("assets registered")
        if options.allow_existing:
            extras.append("existing findings re-sent")
        suffix = f" — {', '.join(extras)}" if extras else ""
        lines.append(
            (
                "secman",
                f"would upload findings at {options.min_severity.value} or above to "
                f"{options.base_url} over {options.transport}{suffix}",
            )
        )
    else:
        lines.append(("secman", "disabled"))

    return lines


def write_plan(plan: ScanPlan, stream: TextIO | None = None) -> None:
    """Print the plan. Writes to the stream and nowhere else."""
    out = stream or sys.stdout
    print("=" * WIDTH, file=out)
    print("Dry run — nothing will be written, sent or uploaded", file=out)
    print("=" * WIDTH, file=out)

    if plan.action != "scan":
        print(f"\nAction: {plan.action}", file=out)

    if plan.targets:
        print(f"\nTargets ({len(plan.targets)}):", file=out)
        for url in plan.targets:
            print(f"  {url}", file=out)

    if plan.config is not None:
        print("\nStages:", file=out)
        for name, detail in _stage_lines(plan.config):
            print(f"  {name:<14} {detail}", file=out)

    if plan.outputs:
        print("\nWould write:", file=out)
        for name, path in plan.outputs:
            print(f"  {name:<14} {path}", file=out)

    integrations = _integration_lines(plan)
    if integrations:
        print("\nIntegrations:", file=out)
        for name, detail in integrations:
            print(f"  {name:<14} {detail}", file=out)

    if plan.secrets:
        print("\nSecrets:", file=out)
        for ref in plan.secrets:
            print(f"  resolved       {ref}", file=out)

    for note in plan.notes:
        print(f"\n{note}", file=out)

    print("\nNothing was written. Re-run without --dry-run to execute this plan.", file=out)

