            "result": tool_result({
                "vulnerabilities": [row] if included else [], "totalPages": 1,
            }),
        })

    uploader = http_uploader(handler) if transport == "http" else mcp_uploader(handler)
    assert uploader.existing_vulnerability_ids(["example.com"], DEFAULT_ID_PREFIX) == {
